"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[7599],{57599:a=>{a.exports=JSON.parse('{"categories":{"prayer-times":"Waktu salat","location":"Lokasi","setup":"Pengaturan salat Anda","athan":"Azan","scheduled":"Azan otomatis","quran":"Al-Qur\'an dan pemutaran","hifz":"Pelatih Hafalan","masjid":"Masjid Saya","ramadan":"Ramadan","islamic-calendar":"Kiblat dan kalender Hijriah","fasting":"Puasa sunah","remembrance":"Zikir, tasbih, dan pengingat harian","help":"Memulai"},"commands":{"Alexa, ask Muslim Companion what is my next prayer":{"does":"Menyebutkan salat berikutnya, waktunya, dan berapa lama lagi, serta waktu iqamah masjid Anda jika Anda mengikutinya.","say":["Alexa, minta Muslim Companion menyebutkan salat berikutnya","Alexa, minta Muslim Companion kapan salat berikutnya"]},"Alexa, ask Muslim Companion when is Maghrib":{"does":"Menyebutkan waktu satu salat hari ini (setelah Isya, Subuh adalah untuk besok).","say":["Alexa, minta Muslim Companion kapan Magrib","Alexa, minta Muslim Companion jam berapa Subuh"]},"Alexa, ask Muslim Companion for today\'s prayer times":{"does":"Membacakan semua waktu hari ini. Di Echo Show juga ditampilkan di layar dengan salat berikutnya dan hitung mundur.","say":["Alexa, minta Muslim Companion waktu salat hari ini","Alexa, minta Muslim Companion waktu salat"]},"Alexa, ask Muslim Companion to use my Echo\'s location":{"does":"Mengatur waktu salat dari alamat Echo Anda (setelah Anda mengizinkan Alamat Perangkat di aplikasi Alexa). Hanya kota dan koordinat perkiraan yang disimpan.","say":["Alexa, minta Muslim Companion memakai lokasi Echo saya","Alexa, minta Muslim Companion memperbarui lokasi saya"]},"Alexa, ask Muslim Companion for prayer times where I am":{"does":"Di aplikasi Alexa di ponsel: waktu salat di tempat Anda berada sekarang, hanya untuk jawaban itu. Azan di rumah tidak berubah.","say":["Alexa, minta Muslim Companion waktu salat di tempat saya berada","Alexa, minta Muslim Companion waktu salat di dekat saya"]},"Yes":{"does":"Menjawab pertanyaan dari Muslim Companion, misalnya apakah memakai lokasi Echo Anda.","say":["Ya","Tidak"]},"Alexa, ask Muslim Companion to read my prayer settings":{"does":"Menyebutkan lokasi, metode perhitungan, dan mazhab Asar Anda, serta cara mengubahnya.","say":["Alexa, minta Muslim Companion membacakan pengaturan salat saya"]},"Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura":{"does":"Mengubah cara waktu salat dihitung: ISNA, Liga Muslim Dunia, Umm al-Qura, Mesir, Karachi, Teluk, Kuwait, Qatar, Singapura, Prancis, Turki, Rusia, Teheran, atau Jafari. Alexa mengonfirmasi dengan waktu salat berikutnya yang baru dan memberi tahu cara kembali.","say":["Alexa, minta Muslim Companion mengatur metode perhitungan saya ke Umm al-Qura","Alexa, beri tahu Muslim Companion untuk memakai metode Liga Muslim Dunia","Alexa, beri tahu Muslim Companion bahwa masjid saya memakai ISNA"]},"Alexa, ask Muslim Companion to set my madhab to Hanafi":{"does":"Mengatur waktu Asar: Hanafi (Asar lebih akhir), atau standar untuk Syafi\'i, Maliki, dan Hanbali.","say":["Alexa, minta Muslim Companion mengatur mazhab saya ke Hanafi","Alexa, beri tahu Muslim Companion bahwa saya mengikuti mazhab Hanafi","Alexa, minta Muslim Companion mengatur mazhab saya ke standar"]},"Alexa, ask Muslim Companion which calculation method should I use":{"does":"Menyarankan metode yang paling banyak dipakai di tempat Anda (misalnya ISNA di Amerika Utara, Diyanet di Turki) dan menawarkan untuk beralih: jawab ya atau tidak.","say":["Alexa, minta Muslim Companion metode perhitungan mana yang sebaiknya saya pakai"]},"Alexa, ask Muslim Companion what calculation method am I using":{"does":"Cara lain menanyakan pengaturan Anda.","say":["Alexa, minta Muslim Companion metode perhitungan apa yang saya pakai","Alexa, minta Muslim Companion apa mazhab saya"]},"Alexa, ask Muslim Companion to play athan":{"does":"Memutar azan sekarang, diikuti doa dan Al-Qur\'an pilihan Anda. Suara yang bisa disebut antara lain Makkah, Madinah, Mishary, dan Zahrani.","say":["Alexa, minta Muslim Companion memutar azan","Alexa, minta Muslim Companion memutar azan Makkah"]},"Alexa, ask Muslim Companion to play fajr athan":{"does":"Memutar azan untuk salat itu (Subuh memakai suara azannya sendiri).","say":["Alexa, minta Muslim Companion memutar azan Subuh","Alexa, minta Muslim Companion memutar azan Magrib"]},"Alexa, ask Muslim Companion to test athan":{"does":"Memutar azan sekali agar Anda bisa memeriksa suaranya di Echo ini.","say":["Alexa, minta Muslim Companion mencoba azan"]},"Alexa, ask Muslim Companion what is my scheduled athan status":{"does":"Memberi tahu apakah azan otomatis aktif.","say":["Alexa, minta Muslim Companion apa status azan terjadwal saya"]},"Alexa, ask Muslim Companion to enable scheduled athan":{"does":"Mengaktifkan azan otomatis. Azan diputar di setiap waktu salat melalui rutinitas Alexa Anda (lihat Panduan Penyiapan).","say":["Alexa, minta Muslim Companion mengaktifkan azan terjadwal"]},"Alexa, ask Muslim Companion to disable scheduled athan":{"does":"Mematikan azan otomatis untuk semua salat sampai Anda menyalakannya lagi.","say":["Alexa, minta Muslim Companion mematikan azan terjadwal"]},"Alexa, ask Muslim Companion to play Surah Al-Kahf":{"does":"Memutar surah apa pun menurut nama atau nomor, diucapkan sesuai kebiasaan Anda (Fatiha atau Fateha, Baqarah atau Surah Baqara, Nisa\u2026), dengan qari Anda atau qari yang Anda sebut (Qari Badar, Maher, Al-Muaiqly, Sudais\u2026), atau dengan terjemahan Inggris atau Urdu setelah setiap ayat.","say":["Alexa, minta Muslim Companion memutar Surah Al-Kahfi","Alexa, minta Muslim Companion memutar Surah Al-Baqarah oleh Qari Badar","Alexa, minta Muslim Companion memutar Al-Fatihah oleh Maher","Alexa, minta Muslim Companion memutar surah nomor 36","Alexa, minta Muslim Companion memutar Surah Yasin dengan terjemahan Inggris"]},"Alexa, ask Muslim Companion which reciters do you have":{"does":"Menyebutkan daftar qari, atau yang namanya diawali huruf tertentu. Jika Alexa tidak mengenal qari yang Anda sebut, ia menyarankan yang berawalan huruf sama.","say":["Alexa, minta Muslim Companion qari apa saja yang tersedia","Alexa, minta Muslim Companion qari mana yang diawali huruf S"]},"Alexa, ask Muslim Companion to turn on Friday Kahf":{"does":"Setiap Jumat, Surah Al-Kahfi diputar setelah azan Subuh (atau Zuhur, diatur di dasbor).","say":["Alexa, minta Muslim Companion menyalakan Al-Kahfi hari Jumat","Alexa, minta Muslim Companion mematikan Al-Kahfi hari Jumat"]},"Alexa, next":{"does":"Saat Al-Qur\'an diputar: surah berikutnya atau sebelumnya. Saat azan dan doa, Berikutnya melompat ke depan.","say":["Alexa, berikutnya","Alexa, sebelumnya"]},"Alexa, start over":{"does":"Memulai surah saat ini dari awal.","say":["Alexa, ulangi dari awal"]},"Alexa, pause":{"does":"Menjeda bacaan dan melanjutkan dari tempat yang sama.","say":["Alexa, jeda","Alexa, lanjutkan"]},"Alexa, stop":{"does":"Menghentikan azan atau bacaan kapan saja.","say":["Alexa, berhenti","Alexa, batal"]},"Alexa, ask Muslim Companion how far am I in the Quran":{"does":"Memberi tahu Perjalanan Al-Qur\'an Anda: waktu mendengar dan seberapa banyak khatam yang sudah Anda dengar.","say":["Alexa, minta Muslim Companion sudah sejauh mana saya dalam Al-Qur\'an"]},"Alexa, shuffle":{"does":"Menjelaskan cara memilih Al-Qur\'an acak atau berkelanjutan di halaman Jadwal Al-Qur\'an.","say":["Alexa, acak","Alexa, ulangi terus"]},"Alexa, ask Muslim Companion to start Hifz":{"does":"Memutar pelajaran Anda saat ini: setiap ayat diulang, lalu seluruh pelajaran bersama. Di Echo Show ayatnya tampil di layar.","say":["Alexa, minta Muslim Companion memulai hafalan"]},"Alexa, tell Muslim Companion I memorized it":{"does":"Menandai pelajaran sudah dihafal dan beralih ke pelajaran berikutnya.","say":["Alexa, beri tahu Muslim Companion saya sudah menghafalnya"]},"Alexa, ask Muslim Companion to repeat each ayah five times":{"does":"Mengatur berapa kali setiap ayat diulang: 1, 3, 5, 7, atau 10.","say":["Alexa, minta Muslim Companion mengulang setiap ayat lima kali"]},"Alexa, ask Muslim Companion how is my Hifz":{"does":"Memberi tahu berapa ayat yang sudah Anda hafal dan pelajaran Anda saat ini.","say":["Alexa, minta Muslim Companion bagaimana hafalan saya"]},"Alexa, ask Muslim Companion when is iqamah":{"does":"Menyebutkan waktu iqamah berikutnya di masjid yang Anda ikuti.","say":["Alexa, minta Muslim Companion kapan iqamah"]},"Alexa, ask Muslim Companion when is jumuah":{"does":"Menyebutkan waktu salat Jumat minggu ini di masjid Anda.","say":["Alexa, minta Muslim Companion kapan salat Jumat"]},"Alexa, ask Muslim Companion to turn on Ramadan mode":{"does":"Menyalakan atau mematikan mode Ramadan: pengingat sahur, berbuka saat Magrib, dan bacaan Tarawih setelah Isya.","say":["Alexa, minta Muslim Companion menyalakan mode Ramadan","Alexa, minta Muslim Companion mematikan mode Ramadan"]},"Alexa, ask Muslim Companion is Ramadan mode on":{"does":"Memberi tahu apakah mode Ramadan aktif.","say":["Alexa, minta Muslim Companion apakah mode Ramadan aktif"]},"Alexa, ask Muslim Companion when is suhoor":{"does":"Menyebutkan kapan sahur berakhir (Subuh) dan kapan berbuka (Magrib).","say":["Alexa, minta Muslim Companion kapan sahur","Alexa, minta Muslim Companion kapan berbuka"]},"Alexa, ask Muslim Companion which way is the Qibla":{"does":"Menyebutkan arah kiblat dari lokasi tersimpan dalam derajat dari utara sejati dan sebagai arah mata angin, serta jarak ke Makkah.","say":["Alexa, minta Muslim Companion ke arah mana kiblat","Alexa, minta Muslim Companion di mana kiblat"]},"Alexa, ask Muslim Companion what is the Hijri date":{"does":"Menyebutkan tanggal Hijriah hari ini (sama dengan aplikasi dan Echo Show Anda), dan apakah hari ini hari istimewa.","say":["Alexa, minta Muslim Companion tanggal Hijriah hari ini","Alexa, minta Muslim Companion tanggal Islam hari ini"]},"Alexa, ask Muslim Companion when is Ramadan":{"does":"Kapan Ramadan, Idul Fitri/Adha, Asyura, Arafah, Tahun Baru Islam, sepuluh malam terakhir, atau ayyamul bidh, dengan hitung mundur. Tanggal mengikuti Umm al-Qura dan bisa berbeda sehari jika hilal dilihat secara lokal.","say":["Alexa, minta Muslim Companion kapan Ramadan","Alexa, minta Muslim Companion berapa hari lagi sampai Idul Fitri","Alexa, minta Muslim Companion kapan ayyamul bidh"]},"Alexa, ask Muslim Companion when is the next Sunnah fast":{"does":"Puasa sunah berikutnya: Senin dan Kamis, ayyamul bidh, Arafah, Asyura, dan enam hari Syawal.","say":["Alexa, minta Muslim Companion kapan puasa sunah berikutnya","Alexa, minta Muslim Companion apakah saya sebaiknya berpuasa besok"]},"Alexa, ask Muslim Companion to turn on fasting reminders":{"does":"Pengingat setelah Isya pada malam sebelum puasa sunah, melalui rutinitas Muslim Companion Anda.","say":["Alexa, minta Muslim Companion menyalakan pengingat puasa","Alexa, minta Muslim Companion mematikan pengingat puasa"]},"Alexa, ask Muslim Companion to play the morning adhkar":{"does":"Ayat Kursi, lalu Al-Ikhlas, Al-Falaq, dan An-Nas masing-masing tiga kali, dibacakan.","say":["Alexa, minta Muslim Companion memutar zikir pagi","Alexa, minta Muslim Companion memutar zikir petang"]},"Alexa, ask Muslim Companion to turn on morning and evening adhkar":{"does":"Memutar zikir pagi setelah Subuh dan zikir petang setelah Asar setiap hari (atau Magrib, diatur di dasbor).","say":["Alexa, minta Muslim Companion menyalakan zikir pagi dan petang","Alexa, minta Muslim Companion mematikan zikir petang"]},"Alexa, ask Muslim Companion to start tasbih":{"does":"Menghitung zikir bersama Anda dengan tempo lembut. Tanpa zikir yang disebut, ia memandu tasbih setelah salat: 33 Subhanallah, 33 Alhamdulillah, dan 34 Allahu Akbar. Di Echo Show, ketuk layar untuk menghitung.","say":["Alexa, minta Muslim Companion memulai tasbih","Alexa, minta Muslim Companion menghitung 33 subhanallah"]},"Alexa, ask Muslim Companion for today\'s dua":{"does":"Doa, hadis, atau Nama Allah harian yang singkat beserta sumbernya, ditinjau ulama sebelum diterbitkan.","say":["Alexa, minta Muslim Companion doa hari ini","Alexa, minta Muslim Companion hadis hari ini","Alexa, minta Muslim Companion Nama Allah hari ini"],"soonNote":"Segera hadir: setiap doa, hadis, dan Nama diperiksa ulama terlebih dahulu"},"Alexa, open Muslim Companion":{"does":"Memulai skill (memutar azan untuk salat saat ini).","say":["Alexa, buka Muslim Companion"]},"Alexa, ask Muslim Companion for help":{"does":"Menyebutkan apa saja yang bisa Anda tanyakan.","say":["Alexa, minta Muslim Companion bantuan"]}}}')}}]);